/* =============================================================================
 * build.js — 이 빌드가 무엇인지 (가장 먼저 로드됩니다)
 *
 * 같은 코드가 두 가지 모습으로 돕니다.
 *
 *   개발 빌드 (release: false)
 *     - 모든 요소에 고유번호 배지가 붙습니다 (P02-B17 같은 것)
 *     - 아무 요소나 눌러 메모를 남길 수 있습니다 (f 키)
 *     - 시드 주입 · 내장 샘플 판독 · 실패 화면 시연 같은 도구가 보입니다
 *     이건 만드는 사람을 위한 화면입니다.
 *
 *   배포 빌드 (release: true)
 *     - 위의 것이 전부 사라집니다
 *     쓰는 사람을 위한 화면입니다.
 *
 * 왜 파일 하나로 가르는가
 *   이 앱은 빌드 도구가 없습니다 — <script> 태그로만 돕니다. 번들러가
 *   없으니 "빌드 시 제거" 같은 것도 없습니다. 그래서 플래그 하나를 맨
 *   앞에서 켜고, 도구성 UI 는 전부 이 플래그를 물어보게 했습니다.
 *   tools/build-release.js 가 이 파일만 바꿔 끼웁니다.
 *
 * 규칙: 이 플래그는 "보여줄까 말까" 에만 씁니다. 계산이나 저장이 빌드에
 * 따라 달라지면, 개발 빌드에서 통과한 검증이 배포 빌드를 보증하지
 * 못하게 됩니다.
 * ========================================================================== */
(function (global) {
  'use strict';
  global.MB_BUILD = {
    release: false,
    version: 'dev',
    builtAt: null,
    /** 개발용 도구를 보여줄까 */
    get tools() { return !this.release; }
  };
})(window);
